% Function to calculate the relaxation modulus based on the Weichert Model
% (expansion of the Prony series). Inputs the time array, raw relaxation
% modulus data, and number of desired terms, and outputs the relaxation
% modulus and tau and modulus coefficients generated by the Weichert model.

function [RelMod,tau,EValues] = calculate_weichert(t,relax,N)

    Index = round(linspace(1,length(t),N)); % Indices for example values based on the number of desired terms, evenly distributed
    
    tau = t(Index); % Pulls time values
    tau = tau - tau(1); % Normalizes time values (begin at 0)
    ERel = relax(Index); % Pulls relaxation modulus values
    
    %% Find Matrix of Coefficients for the System of Linear Equations
    coef = zeros(length(tau)); % Preallocate coefficient matrix
    coef(:,1) = 1; % Coefficients of the first row are all 1, since it is for t=0
    coef(1,:) = 1; % Coefficients of the first column are all 1, since the E0 value is constant
    
    
    for i = 2:length(tau)
        % Loops through each row skipping the first, representing each equation
    
        for j = 2:length(ERel)
            % Loops through each column of the current row, skipping the first,
            % representing each term in the current equation
    
            coef(i,j) = exp(-tau(i)/tau(j)); % Calculates the coefficient for the current position
    
        end
    
    end
    
    %% Solve the System of Linear Equations
    EValues = (coef) \ ERel; % solves the system of linear equations
    
    % Solve for E over time
    RelMod = EValues(1); % Initailize with E0
    
    for i = 2:length(tau)
        % Solve each term of the equation and add it to the total E
        RelMod = RelMod + EValues(i)*exp(-t/tau(i));
    
    end

end